class TestEmbedLimits:
    """Ensure help pages and .sh results stay within Discord embed limits."""

    _categories = tuple(
        c.lower() for c in (
            "setup", "moving", "home", "handling", "infos", "presets", "voting",
            "nominations", "lists", "utility", "other", "meetupmatrix", "economy",
            "botc", "surveillance", "analytics", "status", "location", "dashboard",
            "gamemanager", "library", "games", "auction", "birthdays", "calendar",
            "draft", "sticky", "sendrole", "download",
        )
    )

    def _collect_help_embeds(self):
        bot = MagicMock()
        cog = help_misc_cog.Other(bot)
        captured = []

        async def capture(*args, **kwargs):
            captured.append((args, kwargs))

        cog.send_help_page = capture
        ctx = MagicMock()
        sent = []

        async def fake_send(*a, **k):
            sent.append(k)
            return MagicMock()

        ctx.send = fake_send
        for cat in self._categories:
            _run(cog.help.callback(cog, ctx, cat))
            _run(cog.help2.callback(cog, ctx, cat))
        _run(cog.help.callback(cog, ctx, None))
        _run(cog.help2.callback(cog, ctx, None))
        embeds = []
        for args, _ in captured:
            embeds += [a for a in args[1:] if isinstance(a, discord.Embed)]
        embeds += [k["embed"] for k in sent if isinstance(k.get("embed"), discord.Embed)]
        return embeds

    def test_help_pages_within_discord_embed_limits(self):
        embeds = self._collect_help_embeds()
        assert embeds, "no help embeds were collected"
        for eb in embeds:
            assert len(eb.fields) <= 25, f"{eb.title}: {len(eb.fields)} fields in one embed"
            for f in eb.fields:
                assert len(f.value) <= 1024, f"{eb.title} field '{f.name}': {len(f.value)} chars"
            if eb.title:
                assert len(eb.title) <= 256, f"{eb.title}: title len {len(eb.title)}"
            if eb.description:
                assert len(eb.description) <= 4096, f"{eb.title}: desc len {len(eb.description)}"
            total = len(eb.title or "") + len(eb.description or "") + sum(
                len(f.name) + len(f.value) + 1 for f in eb.fields
            )
            assert total <= 6000, f"{eb.title}: embed total {total}"

    def test_searchhelp_chunks_fields_within_1024(self):
        bot = MagicMock()
        cog = help_misc_cog.Other(bot)
        ctx = MagicMock()
        sent = []

        async def fake_send(*a, **k):
            sent.append(k)
            return MagicMock()

        ctx.send = fake_send
        _run(cog.searchhelp.callback(cog, ctx, keyword="a"))
        embeds = [k["embed"] for k in sent if isinstance(k.get("embed"), discord.Embed)]
        assert embeds, "searchhelp produced no embeds"
        for eb in embeds:
            assert len(eb.fields) <= 25, f".sh: {len(eb.fields)} fields in one embed"
            for f in eb.fields:
                assert len(f.value) <= 1024, f".sh field '{f.name}': {len(f.value)} chars"
            total = len(eb.title or "") + len(eb.description or "") + sum(
                len(f.name) + len(f.value) + 1 for f in eb.fields
            )
            assert total <= 6000, f".sh: embed total {total}"


def _fake_pin(author, content, mid, attachments=()):
    """Build a stand-in for a pinned discord.Message."""
    from datetime import datetime

    return types.SimpleNamespace(
        author=types.SimpleNamespace(display_name=author, name=author.lower()),
        content=content,
        created_at=datetime(2026, 1, 1, 12, 0),
        jump_url=f"https://discord.com/channels/1/{mid}",
        attachments=[types.SimpleNamespace(url=u) for u in attachments],
    )


class TestFirstpinMerge:
    """`.firstpin [n]` merges the first n pinned messages into a single embed."""

    @classmethod
    def _run_firstpin(cls, count, pins, admin=True):
        cog = help_misc_cog.Other(MagicMock())
        ctx = MagicMock()
        ctx.author.guild_permissions.administrator = admin
        ctx.guild.id = 1
        sent = []

        async def fake_send(*a, **k):
            sent.append((a, k))

        ctx.send = fake_send
        channel = MagicMock()

        async def fake_pins():
            return pins

        channel.pins = fake_pins
        with patch.object(help_misc_cog, "load_guild_data", return_value={"alive_role_name": "Alive"}):
            _run(cog.firstpin.callback(cog, ctx, count, channel))
        return sent

    @staticmethod
    def _only_embed(sent):
        assert len(sent) == 1, f"expected one send, got {len(sent)}"
        _, kwargs = sent[0]
        assert "embed" in kwargs, "expected a single embed"
        return kwargs["embed"]

    # Discord returns pins newest-first, so the oldest pin is the last element.
    PINS = [_fake_pin(f"Author{i}", f"body {i}", 100 - i) for i in range(5)]

    def test_default_merges_only_the_oldest_pin(self):
        """No argument keeps the original single-pin behaviour."""
        embed = self._only_embed(self._run_firstpin(1, self.PINS))
        assert embed.title == "First Pinned Message"
        assert "body 4" in embed.description
        assert "body 0" not in embed.description

    def test_merges_first_n_oldest_pins(self):
        """`.firstpin 3` merges the three oldest pins, oldest first."""
        embed = self._only_embed(self._run_firstpin(3, self.PINS))
        assert embed.title == "First 3 Pinned Messages"
        for body in ("body 2", "body 3", "body 4"):
            assert body in embed.description
        assert "body 1" not in embed.description
        assert embed.description.index("body 4") < embed.description.index("body 2")

    def test_single_pin_merge_has_no_numbered_label(self):
        """A one-message merge should not render a stray '1.' prefix."""
        embed = self._only_embed(self._run_firstpin(1, self.PINS))
        assert "**Author4**" in embed.description
        assert "**1. Author4**" not in embed.description

    def test_labels_each_message_when_merging(self):
        """Merged messages are numbered so their order stays readable."""
        embed = self._only_embed(self._run_firstpin(3, self.PINS))
        for index, author in ((1, "Author4"), (2, "Author3"), (3, "Author2")):
            assert f"**{index}. {author}**" in embed.description

    def test_jump_links_laid_out_one_per_line(self):
        """Every merged message gets its own jump link in a single field."""
        embed = self._only_embed(self._run_firstpin(3, self.PINS))
        assert len(embed.fields) == 1
        links = embed.fields[0].value.splitlines()
        assert len(links) == 3
        for index, pin in enumerate(reversed(self.PINS[-3:]), start=1):
            assert pin.jump_url in links[index - 1]

    def test_clamps_to_available_pins(self):
        """Asking for more pins than exist shows what is there, without erroring."""
        embed = self._only_embed(self._run_firstpin(9, self.PINS))
        assert embed.title == "First 5 Pinned Messages"

    def test_attachment_urls_are_kept(self):
        """Attachment links would otherwise be lost when merging."""
        pins = [_fake_pin("A", "see file", 1, attachments=["https://cdn.example/img.png"])]
        embed = self._only_embed(self._run_firstpin(1, pins))
        assert "https://cdn.example/img.png" in embed.description

    def test_empty_content_placeholder(self):
        """A content-less pin still renders a block rather than vanishing."""
        embed = self._only_embed(self._run_firstpin(1, [_fake_pin("A", "   ", 1)]))
        assert "*[No content]*" in embed.description

    @pytest.mark.parametrize("bad", [0, -1, 11, 99])
    def test_rejects_out_of_range_counts(self, bad):
        """Counts outside 1-10 are refused before any embed is built."""
        sent = self._run_firstpin(bad, self.PINS)
        args, kwargs = sent[0]
        assert "embed" not in kwargs, "an embed was sent for an invalid count"
        assert "between 1 and 10" in args[0]

    def test_no_pins_reports_and_sends_no_embed(self):
        sent = self._run_firstpin(3, [])
        args, kwargs = sent[0]
        assert "embed" not in kwargs
        assert "No pinned messages" in args[0]

    @pytest.mark.parametrize("count,body_len", [(1, 10000), (3, 17000), (10, 2100)])
    def test_merged_embed_stays_within_discord_limits(self, count, body_len):
        """Long merges must still fit one embed: desc<=4096, field<=1024, total<=6000."""
        pins = [_fake_pin(f"A{i}", ("line %d " % i) * (body_len // 7), 100 - i) for i in range(count)]
        embed = self._only_embed(self._run_firstpin(count, pins))
        assert len(embed.description) <= 4096, f"description {len(embed.description)}"
        for f in embed.fields:
            assert len(f.value) <= 1024, f"field {len(f.value)}"
        total = len(embed.title) + len(embed.description) + sum(
            len(f.name) + len(f.value) + 1 for f in embed.fields
        ) + len(embed.footer.text or "")
        assert total <= 6000, f"embed total {total}"
        embed.to_dict()

    def test_overlong_merge_is_truncated_with_a_marker(self):
        """Rather than fail, an oversized merge says that it was cut."""
        pins = [_fake_pin("A", "z" * 9000, 1)]
        embed = self._only_embed(self._run_firstpin(1, pins))
        assert "truncated" in embed.description

    def test_truncation_uses_most_of_the_budget(self):
        """A clean break near the end must not shrink the embed far below the cap."""
        pins = [_fake_pin(f"A{i}", ("line %d " % i) * 300, 100 - i) for i in range(10)]
        embed = self._only_embed(self._run_firstpin(10, pins))
        assert len(embed.description) > 3900, f"only used {len(embed.description)} of 4096"


class TestTruncateHelper:
    """Unit coverage for the shared embed truncation helper."""

    def test_short_text_untouched(self):
        assert help_misc_cog._truncate("hello", 100) == "hello"

    def test_result_never_exceeds_limit(self):
        out = help_misc_cog._truncate("a" * 5000, 4096)
        assert len(out) <= 4096

    def test_prefers_a_clean_break(self):
        text = ("a" * 3000) + "\n" + ("b" * 3000)
        out = help_misc_cog._truncate(text, 4096)
        assert "truncated" in out
        assert not out[: -len("\n\n*… Output truncated. Use `.firstpin 1` to view a single message.*")].endswith("a")

    def test_hard_cuts_when_no_break_exists(self):
        out = help_misc_cog._truncate("z" * 9000, 4096)
        assert len(out) <= 4096
        assert "truncated" in out




