class TestAvatarCommand:
    """.avatar shows the caller's own avatar, or the mentioned member's."""

    @staticmethod
    def _member(name, colour_value=0):
        member = MagicMock()
        member.display_name = name
        member.color = discord.Color(colour_value)
        avatar = MagicMock()
        avatar.url = f"https://cdn.example/{name}.png"
        avatar.replace.return_value.url = f"https://cdn.example/{name}-1024.png"
        member.display_avatar = avatar
        return member

    @staticmethod
    def _ctx(author):
        ctx = MagicMock()
        ctx.author = author
        ctx.send = AsyncMock()
        return ctx

    @pytest.mark.asyncio
    async def test_shows_own_avatar_by_default(self):
        author = self._member("Alice")
        ctx = self._ctx(author)

        await help_misc_cog.Other.avatar.callback(
            help_misc_cog.Other(MagicMock()), ctx, None
        )

        embed = ctx.send.await_args.kwargs["embed"]
        assert embed.title == "Alice's Avatar"
        assert embed.image.url == "https://cdn.example/Alice.png"
        assert "Alice" in embed.footer.text

    @pytest.mark.asyncio
    async def test_shows_mentioned_members_avatar(self):
        author = self._member("Alice")
        target = self._member("Bob", colour_value=0xFF0000)
        ctx = self._ctx(author)

        await help_misc_cog.Other.avatar.callback(
            help_misc_cog.Other(MagicMock()), ctx, target
        )

        embed = ctx.send.await_args.kwargs["embed"]
        assert embed.title == "Bob's Avatar"
        assert embed.image.url == "https://cdn.example/Bob.png"
        assert embed.color.value == 0xFF0000
